import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Maximum number of processing attempts per job, including the first. */
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_FAILURE = 'transient failure';
export const WORKER_HEARTBEAT = 'worker';
/** The worker writes a heartbeat about once a second; it counts as down after this long without one. */
export const HEARTBEAT_TIMEOUT_MS = 3000;

interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

const JOB_COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, completed, result_output, error, created_at, updated_at';

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output ?? '' } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

type Param = string | number | null;

function one(db: DatabaseSync, sql: string, ...params: Param[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

/** Runs `fn` inside an immediate write transaction, so concurrent writers wait instead of interleaving. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction was already closed
    }
    throw e;
  }
}

export type SubmitOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or handles an idempotent replay. The key check and the insert share one
 * transaction, and the key is unique in the database, so a key never creates two jobs.
 */
export function submitJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | undefined): SubmitOutcome {
  return transaction(db, (): SubmitOutcome => {
    if (idempotencyKey !== undefined) {
      const existing = one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`, idempotencyKey);
      if (existing) {
        const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, run_after, idempotency_key, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, Date.now(), idempotencyKey ?? null, now, now);
    return { kind: 'created', job: toJob(one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`, id)!) };
  });
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`, id);
  return row ? toJob(row) : undefined;
}

export function listJobs(db: DatabaseSync): Job[] {
  return (db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[]).map(toJob);
}

/** Moves the oldest queued job that is ready to run into `running` and counts the new attempt. */
export function claimNextJob(db: DatabaseSync): Job | undefined {
  return transaction(db, () => {
    const next = one(db, `SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`, Date.now());
    if (!next) return undefined;
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?`).run(
      new Date().toISOString(),
      next.seq,
    );
    return toJob(one(db, `SELECT ${JOB_COLUMNS} FROM jobs WHERE seq = ?`, next.seq)!);
  });
}

/**
 * Jobs left `running` by a worker that died are reset so they are processed again. An interrupted
 * attempt still counts as started, so a job that has used all its attempts fails instead of
 * running a fourth time.
 */
export function recoverInterruptedJobs(db: DatabaseSync): void {
  const now = new Date().toISOString();
  transaction(db, () => {
    db.prepare(`UPDATE jobs SET status = 'failed', error = ?, updated_at = ? WHERE status = 'running' AND attempts >= ?`).run(
      TRANSIENT_FAILURE,
      now,
      MAX_ATTEMPTS,
    );
    db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`).run(now);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?`).run(completed, new Date().toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, total: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(total, output, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(`UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE id = ?`).run(
    error,
    new Date().toISOString(),
    id,
  );
}

/** Returns a failed attempt to the queue, ready to run again once `runAfter` (epoch ms) has passed. */
export function requeueJob(db: DatabaseSync, id: string, runAfter: number): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE id = ?`).run(
    runAfter,
    new Date().toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync): void {
  db.prepare(
    `INSERT INTO heartbeats (name, at) VALUES (?, ?) ON CONFLICT (name) DO UPDATE SET at = excluded.at`,
  ).run(WORKER_HEARTBEAT, Date.now());
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare(`DELETE FROM heartbeats WHERE name = ?`).run(WORKER_HEARTBEAT);
}

export function workerIsUp(db: DatabaseSync): boolean {
  const row = one(db, `SELECT at FROM heartbeats WHERE name = ?`, WORKER_HEARTBEAT) as unknown as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at < HEARTBEAT_TIMEOUT_MS;
}

