import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult =
  | { ok: true; job: NewJob; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

export interface RawSubmission {
  contentType: string | undefined;
  /** The raw body, or null when it was too large to read. */
  body: string | null;
  idempotencyKey: string | string[] | undefined;
}

const bodyError = (message: string): ParseResult => ({ ok: false, fields: [{ field: 'body', message }] });

/** Checks a submission. Any problem with the body as a whole is reported alone as field "body". */
export function parseSubmission(raw: RawSubmission): ParseResult {
  const mediaType = raw.contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') return bodyError('Content-Type must be application/json.');
  if (raw.body === null) return bodyError('Body is too large.');

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw.body);
  } catch {
    return bodyError('Body is not valid JSON.');
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return bodyError('Body must be a JSON object.');
  }

  const obj = parsed as Record<string, unknown>;
  const fields: FieldError[] = [];
  for (const key of Object.keys(obj)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  const steps = obj.steps === undefined ? DEFAULT_STEPS : obj.steps;
  if (!isIntegerInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });

  const failAttempts = obj.failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : obj.failAttempts;
  if (!isIntegerInRange(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });

  let idempotencyKey: string | undefined;
  if (raw.idempotencyKey !== undefined) {
    if (typeof raw.idempotencyKey === 'string' && IDEMPOTENCY_KEY.test(raw.idempotencyKey)) {
      idempotencyKey = raw.idempotencyKey;
    } else {
      fields.push({ field: 'Idempotency-Key', message: 'Must be 1 to 128 letters, digits, "_" or "-".' });
    }
  }

  if (fields.length > 0) return { ok: false, fields };
  return {
    ok: true,
    job: { input: input as string, steps: steps as number, failAttempts: failAttempts as number },
    idempotencyKey,
  };
}

function isIntegerInRange(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

