import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  MAX_ATTEMPTS,
  TRANSIENT_FAILURE,
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  recoverInterruptedJobs,
  requeueJob,
  setProgress,
  writeHeartbeat,
  type Job,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

/** Time for one processing step. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
const RETRY_DELAY_MS = 500;
const HEARTBEAT_INTERVAL_MS = 1000;
/** How long an idle worker waits before checking the queue again. */
const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// Jobs left running by a previous worker that died are processed again.
recoverInterruptedJobs(db);
writeHeartbeat(db);
const heartbeat = setInterval(() => writeHeartbeat(db), HEARTBEAT_INTERVAL_MS);

/**
 * Runs one attempt. The attempt number is `job.attempts`, which was incremented when the job was
 * claimed. Attempt n fails at its first step, before any progress, when n <= failAttempts.
 * Returns early, leaving the job `running`, if the worker is asked to stop mid-attempt; the next
 * worker start then recovers it.
 */
async function runAttempt(store: DatabaseSync, job: Job): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) {
      failJob(store, job.id, TRANSIENT_FAILURE);
    } else {
      requeueJob(store, job.id, Date.now() + RETRY_DELAY_MS);
    }
    return;
  }

  const input = job.input;
  for (let step = 1; step <= job.steps; step++) {
    if (stopping) return;
    await sleep(STEP_MS);
    setProgress(store, job.id, step);
  }
  completeJob(store, job.id, input.toUpperCase(), job.steps);
}

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNextJob(db);
    if (job) {
      await runAttempt(db, job);
    } else {
      await sleep(IDLE_POLL_MS);
    }
  } catch (e) {
    console.error('worker error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
clearHeartbeat(db);
db.close();
console.log('worker stopped');

